mapper.select:
SELECT h.user_search_history_id, h.target_user_no, h.searched_at, u.nickname, ( SELECT rp.profile_file_id FROM ultary_pet rp WHERE rp.user_no = u.user_no AND rp.is_deleted = 0 AND rp.profile_file_id IS NOT NULL ORDER BY rp.priority ASC, rp.pet_id ASC LIMIT 1 ) AS profileFileId FROM ultary_user_search_history h INNER JOIN ultary_user u ON u.user_no = h.target_user_no AND u.withdrawal_status = 'ACTIVE' WHERE h.user_no = #{viewerUserNo} AND NOT EXISTS ( SELECT 1 FROM ultary_user_block b WHERE b.is_deleted = 0 AND ( (b.blocker_user_no = #{viewerUserNo} AND b.blocked_user_no = h.target_user_no) OR (b.blocker_user_no = h.target_user_no AND b.blocked_user_no = #{viewerUserNo}) ) )
AND ( h.searched_at < #{cursorSearchedAt} OR ( h.searched_at = #{cursorSearchedAt} AND h.user_search_history_id < #{cursorHistoryId} ) )
ORDER BY h.searched_at DESC, h.user_search_history_id DESC LIMIT #{limit}

mapper.delete:
DELETE FROM ultary_user_search_history
WHERE user_no = #{userNo}
  AND user_search_history_id = #{userSearchHistoryId}
